Output the entire module as a single fenced ```python code block and nothing else.
RESPONSE: ```python
def sphere(x: list) -> float:
    return sum([i**2 for i in x])

class Particle:
    def __init__(self, x0: list):
        self.position = x0
        self.velocity = [0] * len(x0)
        self.best_position = x0
        self.best_value = evaluate(self, sphere)

    def evaluate(self, costFunc: callable) -> float:
        return costFunc(self.position)

    def update_velocity(self, pos_best_g: list) -> None:
        for i in range(len(self.position)):
            self.velocity[i] = 0.729 * self.velocity[i] + 2 * (pos_best_g[i] - self.position[i])

    def update_position(self, bounds: list) -> None:
        for i in range(len(self.position)):
            self.position[i] = self.position[i] + self.velocity[i]
            if self.position[i] > bounds[i][1]:
                self.position[i] = bounds[i][1]
            elif self.position[i] < bounds[i][0]:
                self.position[i] = bounds[i][0]
```

